head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF10002";
scwin.ifrCtrl = null;
scwin.gUrl = undefined;
scwin.dsclViewerUrl = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.ifrCtrl = $c.util.getComponent('ifrCtrl');
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10002.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ko_onclick
 * @description btn_ko 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ko_onclick = function(e){
    try {
        scwin.getBodyContentByLangGb('KO')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10002.btn_ko_onclick' }); }
};

/**
 * @method
 * @name btn_en_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_en_onclick = function(e){
    try {
        scwin.getBodyContentByLangGb('EN')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10002.btn_en_onclick' }); }
};

/**
 * @method
 * @name viewer_btn_onclick
 * @description 「공시뷰어 새창열기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.viewer_btn_onclick = function(e){
    try {
        scwin.addViewerOpen()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10002.viewer_btn_onclick' }); }
};

/**
 * @method
 * @name newWindowId_onclick
 * @description newWindowId 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.newWindowId_onclick = function(e){
    try {
        scwin.openNewWindow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10002.newWindowId_onclick' }); }
};

/**
 * @method
 * @name img_17_onclick
 * @description img_17 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_17_onclick = async function(e){
    try {
        await scwin.DocPrint();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10002.img_17_onclick' }); }
};

/**
 * @method
 * @name img_18_onclick
 * @description img_18 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_18_onclick = function(e){
    try {
        $c.win.openPopup('', { id: "_self", type: "pageFramePopup" }, {});$c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10002.img_18_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_viewerUrl
 * @description viewer Url 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_viewerUrl = async function () {
    const sbmOptions = {
        id: "tx_fn_viewerUrl",
        method: "post",
        action: "/EsgSearch.do",
        ref: "dma_viewerUrlReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name DocPrint
 * @description Doc Print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.DocPrint = async function () {
    const docUrl = sessionStorage.getItem("gDocUrl");
    const printType = sessionStorage.getItem("gSndlocTpCd");
    const vFromUpclssCd = sessionStorage.getItem("gFromUpclssCd");
    const printAcptNo = sessionStorage.getItem("gPrintAcptNo");
    const printDocNo = sessionStorage.getItem("gPrintDocNo");
    if (printType === '20' && vFromUpclssCd !== '01') {
        const usrl = "/disclsdocviewer/pdfView.jsp?type=pdf" + "&acptNo=" + printAcptNo + "&docNo=" + printDocNo + "&SCREN_ID=" + "/ui/jsp/JLDSTF10002.xml" + "&SCREN_PROCES_TP_CD=05" + "&docpath=" + docUrl;
        const winTitle = "공시뷰어";
        window.open(usrl, "testPop", "left=0,top=0,width=850,height=750,resizable=yes,scrollbars=no,location=no,status=no");
    } else {
        scwin.ifrCtrl.focus();
        await $c.win.print();
    }
};

/**
 * @method
 * @name showPrintForm
 * @description show Print Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showPrintForm = async function () {
    const url = location.href;
    if (url.indexOf("?") !== -1) {
        const queryString = url.substring(url.indexOf("?") + 1);
        const paramList = queryString.split("&");
        for (i = 0; i < paramList.length; i++) {
            let tmp = paramList[i];
            tmp = tmp.split("=");
            if (tmp[0] === "gPrintUrl") {
                sessionStorage.setItem(tmp[0], decodeURIComponent(tmp[1]));
            } else {
                sessionStorage.setItem(tmp[0], tmp[1]);
            }
        }
    }
    scwin.showLangBtn();
    const gPrintUrl = sessionStorage.getItem("gPrintUrl");
    scwin.gUrl = gPrintUrl;
    $c.util.getComponent("ifrCtrl").src = scwin.gUrl;
    await scwin.viewerBtnStyleCheck();
};

/**
 * @method
 * @name openNewWindow
 * @description open New Window 처리
 * @returns {void}
 * @hidden N
 */
scwin.openNewWindow = function () {
    const randNum = Math.floor(Math.random() * (99999)) + 1;
    const url = location.href;
    if (url.length > 55) {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(scwin.gUrl), { width: "850", height: "750", resizable: true, scrollbars: true, type: "pageFramePopup" }, {});
    } else {
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).Potential).Provider.Provider("/").window.open(scwin.gUrl, "viewer_pop2" + randNum, "left=0,top=0,width=850,height=750,resizable=yes,scrollbars=yes,location=no,status=no");
    }
};

/**
 * @method
 * @name showLangBtn
 * @description show Lang Btn 처리
 * @returns {void}
 * @hidden N
 */
scwin.showLangBtn = function () {
    const procs_063 = sessionStorage.getItem("gProcs_063");
    const procs_070 = sessionStorage.getItem("gProcs_070");
    const gLangTpCd = sessionStorage.getItem("gLangTpCd");
    const gSvcStatYn = sessionStorage.getItem("gSvcStatYn");
    const submitSysTp = sessionStorage.getItem("gSubmitSysTp");
    const gAttachDocYn = sessionStorage.getItem("gAttachDocYn");
    const procs_111 = sessionStorage.getItem("gProcs_111");
    const gSecuGrpEF = sessionStorage.getItem("gSecuGrpEF");
    const gDisclsEnYn = sessionStorage.getItem("gDisclsEnYn");
    const gAcptNo = sessionStorage.getItem("gAcptNo");
    const gSvrGubun = sessionStorage.getItem("gSvrGubun");
    const aKo = $c.util.getComponent('lang_ko');
    if (gSvrGubun === 'dev' || (gSvrGubun !== 'dev' && gAcptNo > '20100913000000')) {
        if (gAttachDocYn === 'N' && (procs_070 > 0 || (procs_111 > 0 && gDisclsEnYn === 'Y')) && gSvcStatYn === 'Y') {
            aKo.setStyle('visibility', "visible");
            $c.util.getComponent('btn_ko').src = "/img/btn_korean.gif";
            $c.util.getComponent('btn_en').src = "/img/btn_english_1.gif";
            if (gLangTpCd === '1') {
                aKo.setStyle('visibility', "hidden");
            }
        }
        if (submitSysTp === '1') {
            aKo.setStyle('visibility', "visible");
            $c.util.getComponent('btn_ko').src = "/img/btn_korean_1.gif";
            $c.util.getComponent('btn_en').src = "/img/btn_english.gif";
        }
    }
};

/**
 * @method
 * @name getBodyContentByLangGb
 * @description get Body Content By Lang Gb 처리
 * @param {*} langGb langGb
 * @returns {void}
 * @hidden N
 */
scwin.getBodyContentByLangGb = function (langGb) {
    let vViewLangTp = '0';
    if (langGb === 'KO') {
        vViewLangTp = '0';
        scwin.ifrCtrl.location.href = $c.str.replaceAll(scwin.gUrl, "&VIEW_LANG_TP_CD=1", "&VIEW_LANG_TP_CD=0");
        $c.util.getComponent('btn_ko').src = "/img/btn_korean.gif";
        $c.util.getComponent('btn_en').src = "/img/btn_english_1.gif";
    } else {
        vViewLangTp = '1';
        scwin.ifrCtrl.location.href = $c.str.replaceAll(scwin.gUrl, "&VIEW_LANG_TP_CD=0", "&VIEW_LANG_TP_CD=1");
        $c.util.getComponent('btn_ko').src = "/img/btn_korean_1.gif";
        $c.util.getComponent('btn_en').src = "/img/btn_english.gif";
    }
};

/**
 * @method
 * @name viewerBtnStyleCheck
 * @description viewer Btn Style Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewerBtnStyleCheck = async function () {
    const url = sessionStorage.getItem("gPrintUrl");
    let formCd = "";
    let disclsDocNo = "";
    if (url.indexOf("?") !== -1) {
        const queryString = url.substring(url.indexOf("?") + 1);
        const paramList = queryString.split("&");
        for (i = 0; i < paramList.length; i++) {
            let tmp = paramList[i];
            tmp = tmp.split("=");
            if (tmp[0] === "FORM_CD") {
                formCd = tmp[1];
            } else {
                if (tmp[0] === "DOC_NO") {
                    disclsDocNo = tmp[1];
                }
            }
        }
    }
    if (formCd === "99667" || formCd === "99926" || formCd === "99927") {
        await scwin.tx_fn_viewerUrl(disclsDocNo);
    }
};

/**
 * @method
 * @name addViewerOpen
 * @description add Viewer Open 처리
 * @returns {void}
 * @hidden N
 */
scwin.addViewerOpen = function () {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })('microsoft-edge:' + scwin.dsclViewerUrl), { id: '_self' }, {});
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
